package com.fandazi.feature.payment;
import com.fandazi.feature.DomainException; import com.fandazi.feature.order.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class PaymentService { private final OrderService orders; public PaymentService(OrderService orders){this.orders=orders;} @Transactional public OrderEntity pay(Long userId,Long orderId){return pay(userId,orderId,"legacy-"+java.util.UUID.randomUUID());} @Transactional public OrderEntity pay(Long userId,Long orderId,String idempotencyKey){if(idempotencyKey==null||idempotencyKey.isBlank())throw new DomainException("缺少支付幂等键");var order=orders.locked(userId,orderId);if(idempotencyKey.equals(order.getPaymentIdempotencyKey()))return order;if(order.getStatus()!=OrderStatus.PENDING_PAYMENT)throw new DomainException("订单已支付或无法支付");order.setPaymentIdempotencyKey(idempotencyKey);orders.transition(userId,orderId,OrderStatus.PENDING_PAYMENT,OrderStatus.PAID);return orders.transition(userId,orderId,OrderStatus.PAID,OrderStatus.MERCHANT_ACCEPTED);} }
